{
  "items": [
    {
      "name": "MvPowerSeries.weightedOrder_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] [NoZeroDivisors R] (w : σ → ℕ) (f g : MvPowerSeries σ R),\n  MvPowerSeries.weightedOrder w (f * g) = MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g"
    },
    {
      "name": "MvPowerSeries.weightedOrder_prod",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] [NoZeroDivisors R] [Nontrivial R] {ι : Type u_4} (w : σ → ℕ)\n  (f : ι → MvPowerSeries σ R) (s : Finset ι),\n  MvPowerSeries.weightedOrder w (∏ i ∈ s, f i) = ∑ i ∈ s, MvPowerSeries.weightedOrder w (f i)"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R},\n  MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)"
    },
    {
      "name": "MvPowerSeries.weightedOrder_mul_ge",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R},\n  MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)"
    },
    {
      "name": "MvPowerSeries.order_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] [NoZeroDivisors R] (f g : MvPowerSeries σ R),\n  (f * g).order = f.order + g.order"
    }
  ]
}
